import{_ as e,o as a,c as o,a0 as r}from"./chunks/framework.AQcSKqPn.js";const g=JSON.parse('{"title":"AI情报日报 2026-07-28","description":"","frontmatter":{"type":"page","title":"AI情报日报 2026-07-28","tags":["ai","daily-report","情报"],"created":"2026-07-28T00:00:00.000Z"},"headers":[],"relativePath":"daily/ai-report-2026-07-28.md","filePath":"daily/ai-report-2026-07-28.md","lastUpdated":1785204172000}'),d={name:"daily/ai-report-2026-07-28.md"};function i(n,t,l,s,h,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="ai情报日报-2026-07-28" tabindex="-1">AI情报日报 2026-07-28 <a class="header-anchor" href="#ai情报日报-2026-07-28" aria-label="Permalink to &quot;AI情报日报 2026-07-28&quot;">​</a></h1><h2 id="ai-hot-精选" tabindex="-1">AI HOT 精选 <a class="header-anchor" href="#ai-hot-精选" aria-label="Permalink to &quot;AI HOT 精选&quot;">​</a></h2><h3 id="🔥-kimi-k3-开源-2-8t-moe-模型与技术报告" tabindex="-1">🔥 Kimi K3 开源：2.8T MoE 模型与技术报告 <a class="header-anchor" href="#🔥-kimi-k3-开源-2-8t-moe-模型与技术报告" aria-label="Permalink to &quot;🔥 Kimi K3 开源：2.8T MoE 模型与技术报告&quot;">​</a></h3><p>Kimi 发布其最强模型 Kimi K3，2.8T 参数 MoE 模型，具备原生视觉理解和 1M token 上下文窗口。新架构实现每单位计算 2.5 倍的智能提升。开源内容包括模型权重、高性能注意力内核、MoE 通信库及大规模智能体运行环境基础设施。</p><blockquote><p>来源：<a href="https://x.com/Kimi_Moonshot/status/2081760186235289764" target="_blank" rel="noreferrer">Kimi.ai</a></p></blockquote><h3 id="🔥-sglang-miles-为-kimi-k3-提供-day-0-支持" tabindex="-1">🔥 SGLang &amp; Miles 为 Kimi K3 提供 Day-0 支持 <a class="header-anchor" href="#🔥-sglang-miles-为-kimi-k3-提供-day-0-支持" aria-label="Permalink to &quot;🔥 SGLang &amp; Miles 为 Kimi K3 提供 Day-0 支持&quot;">​</a></h3><p>SGLang 和 Miles 为 K3 提供发布当日推理和 RL 训练支持。K3 采用 69 层 KDA 线性注意力与 24 层 MLA 交错的混合架构，在 SGLang 上单卡 batch-1 解码速度约 113 tok/s，结合 DSpark 推测解码可达约 423 tok/s。</p><blockquote><p>来源：<a href="https://www.lmsys.org/blog/2026-07-27-kimi-k3-day0-support" target="_blank" rel="noreferrer">LMSYS Blog</a></p></blockquote><h3 id="👁️-kimi-发布视觉感知基准-perceptionbench" tabindex="-1">👁️ Kimi 发布视觉感知基准 PerceptionBench <a class="header-anchor" href="#👁️-kimi-发布视觉感知基准-perceptionbench" aria-label="Permalink to &quot;👁️ Kimi 发布视觉感知基准 PerceptionBench&quot;">​</a></h3><p>从前沿模型在 42 个基准上的失败模式归纳出的视觉感知基准，将视觉感知拆解为 10 种原子能力，构建 3000 道验证题，每题只考察单一感知能力。</p><blockquote><p>来源：<a href="https://x.com/Kimi_Moonshot/status/2081813202514681878" target="_blank" rel="noreferrer">Kimi.ai</a></p></blockquote><h3 id="🧭-google-ai-overviews-搜索结果出现率升至-43" tabindex="-1">🧭 Google AI Overviews 搜索结果出现率升至 43% <a class="header-anchor" href="#🧭-google-ai-overviews-搜索结果出现率升至-43" aria-label="Permalink to &quot;🧭 Google AI Overviews 搜索结果出现率升至 43%&quot;">​</a></h3><p>一年内从 15% 升至 43%，AI Mode 月访问量从 1.26 亿增至 2.79 亿。用户搜索从短关键词向长自然对话式查询转变。</p><blockquote><p>来源：<a href="https://techcrunch.com/2026/07/27/googles-ai-search-is-rapidly-becoming-the-default-new-data-shows" target="_blank" rel="noreferrer">TechCrunch</a></p></blockquote><h3 id="🛡️-nvidia-等联合成立-open-secure-ai-alliance" tabindex="-1">🛡️ NVIDIA 等联合成立 Open Secure AI Alliance <a class="header-anchor" href="#🛡️-nvidia-等联合成立-open-secure-ai-alliance" aria-label="Permalink to &quot;🛡️ NVIDIA 等联合成立 Open Secure AI Alliance&quot;">​</a></h3><p>NVIDIA、Microsoft、Hugging Face、IBM 等数十家机构联合成立，旨在通过开源模型、工具和框架构建可审查、可定制的 AI 安全防御体系。</p><blockquote><p>来源：<a href="https://blogs.nvidia.com/blog/open-secure-ai-alliance" target="_blank" rel="noreferrer">NVIDIA Blog</a></p></blockquote><h3 id="🔧-github-copilot-发布-harness-工作流" tabindex="-1">🔧 GitHub Copilot 发布 &quot;Harness&quot; 工作流 <a class="header-anchor" href="#🔧-github-copilot-发布-harness-工作流" aria-label="Permalink to &quot;🔧 GitHub Copilot 发布 &quot;Harness&quot; 工作流&quot;">​</a></h3><p>让开发者通过单一 AI 工具完成从原型设计、规划、实现到代码审查的完整软件开发流程，减少工具切换带来的效率损耗。</p><blockquote><p>来源：<a href="https://github.blog/ai-and-ml/github-copilot/the-harness-is-all-you-need-mostly" target="_blank" rel="noreferrer">GitHub Blog</a></p></blockquote><h3 id="🏢-openai-43-5-员工用-chatgpt-做其他岗位的工作" tabindex="-1">🏢 OpenAI：43.5% 员工用 ChatGPT 做其他岗位的工作 <a class="header-anchor" href="#🏢-openai-43-5-员工用-chatgpt-做其他岗位的工作" aria-label="Permalink to &quot;🏢 OpenAI：43.5% 员工用 ChatGPT 做其他岗位的工作&quot;">​</a></h3><p>分析超 80 万条工作相关消息后发现，营销和工程任务交叉最多。用户用 AI 处理合同审查、数据分析、网站故障排查等原由专家负责的工作。该趋势在缺乏专业团队的小公司尤为明显。</p><blockquote><p>来源：<a href="https://the-decoder.com/openai-says-more-workers-are-using-chatgpt-to-do-other-peoples-jobs" target="_blank" rel="noreferrer">The Decoder</a></p></blockquote><h3 id="🎯-leader-skill-开源-将模糊需求转化为-agent-目标" tabindex="-1">🎯 Leader.skill 开源：将模糊需求转化为 Agent 目标 <a class="header-anchor" href="#🎯-leader-skill-开源-将模糊需求转化为-agent-目标" aria-label="Permalink to &quot;🎯 Leader.skill 开源：将模糊需求转化为 Agent 目标&quot;">​</a></h3><p>基于 &quot;目标七问&quot; 方法论，将模糊人类需求转化为 Agent 可独立执行数小时的目标任务书。推荐用 Claude Fable 5 或 Kimi K3 规划目标。</p><blockquote><p>来源：<a href="https://mp.weixin.qq.com/s/AwOk3di8m6eVeIUjzNftgg" target="_blank" rel="noreferrer">数字生命卡兹克</a></p></blockquote><h3 id="🧠-anthropic-澄清开源权重立场" tabindex="-1">🧠 Anthropic 澄清开源权重立场 <a class="header-anchor" href="#🧠-anthropic-澄清开源权重立场" aria-label="Permalink to &quot;🧠 Anthropic 澄清开源权重立场&quot;">​</a></h3><p>CEO Dario Amodei 明确表示从未主张禁止开源权重模型，提出三项实际措施：对华芯片出口管制、打击工业级知识蒸馏、对强大模型进行强制性安全测试。</p><blockquote><p>来源：<a href="https://www.anthropic.com/news/position-open-weights-models" target="_blank" rel="noreferrer">Anthropic</a></p></blockquote><h3 id="📸-openrouter-新增图像生成专用-api" tabindex="-1">📸 OpenRouter 新增图像生成专用 API <a class="header-anchor" href="#📸-openrouter-新增图像生成专用-api" aria-label="Permalink to &quot;📸 OpenRouter 新增图像生成专用 API&quot;">​</a></h3><p>通过 <code>/api/v1/images</code> 端点提供图像生成模型服务，图像理解仍通过 <code>/chat/completions</code>，共用 API Key 和计费体系。</p><blockquote><p>来源：<a href="https://openrouter.ai/blog/tutorials/image-generation-models" target="_blank" rel="noreferrer">OpenRouter</a></p></blockquote><hr><h2 id="小红书爆款-top-10-2026-07-26-趋势数据" tabindex="-1">小红书爆款 TOP 10（2026-07-26 趋势数据） <a class="header-anchor" href="#小红书爆款-top-10-2026-07-26-趋势数据" aria-label="Permalink to &quot;小红书爆款 TOP 10（2026-07-26 趋势数据）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>标题</th><th>作者</th><th>互动量</th><th>点赞</th><th>收藏</th><th>评论</th></tr></thead><tbody><tr><td>1</td><td><strong>男装品牌做的女装设计细节我怎从未听过！</strong></td><td>@喵哇摸娱记</td><td><strong>30w+</strong></td><td>23w+</td><td>6w+</td><td>901</td></tr><tr><td>2</td><td><strong>发现好多大学生不懂邮件礼仪</strong></td><td>@朝朝暮暮有钱存</td><td><strong>25w+</strong></td><td>11w+</td><td>14w+</td><td>670</td></tr><tr><td>3</td><td><strong>&quot;集美貌与才华为一身的女性之友&quot; papi酱</strong></td><td>@莎莎的观影日记</td><td><strong>31w+</strong></td><td>30w+</td><td>7928</td><td>3436</td></tr><tr><td>4</td><td><strong>免费上门的三等功（猫meme）</strong></td><td>@猫meme小作坊</td><td><strong>24w+</strong></td><td>20w+</td><td>3w+</td><td>313</td></tr><tr><td>5</td><td><strong>谁家的小黄球丢在马路上啦</strong></td><td>@陈奶奶爱种地</td><td><strong>23w+</strong></td><td>21w+</td><td>3794</td><td>1w+</td></tr><tr><td>6</td><td><strong>娃从小被练到大</strong></td><td>@十一爸也可以</td><td><strong>26w+</strong></td><td>19w+</td><td>7w+</td><td>4221</td></tr><tr><td>7</td><td><strong>小红书新特效可爱鼠喽！！！</strong></td><td>@胡萝贝糊糊</td><td><strong>30w+</strong></td><td>30w+</td><td>1295</td><td>157</td></tr><tr><td>8</td><td><strong>女孩子礼貌与秩序（看作者喜极而泣）</strong></td><td>@娱你同行</td><td><strong>24w+</strong></td><td>22w+</td><td>1w+</td><td>1653</td></tr><tr><td>9</td><td><strong>但你却拥有绝对不会挨揍的理由（猫meme）</strong></td><td>@三败涂地</td><td><strong>20w+</strong></td><td>15w+</td><td>3w+</td><td>1w+</td></tr><tr><td>10</td><td><strong>好累啊这个视频里到底加了什么</strong></td><td>@娱圈小福星</td><td><strong>19w+</strong></td><td>16w+</td><td>2w+</td><td>1759</td></tr></tbody></table><h3 id="💡-趋势观察" tabindex="-1">💡 趋势观察 <a class="header-anchor" href="#💡-趋势观察" aria-label="Permalink to &quot;💡 趋势观察&quot;">​</a></h3><ul><li><strong>猫meme</strong> 持续霸榜，两条猫meme内容同时进入 TOP 10，搞笑/抽象赛道表现强劲</li><li><strong>实用干货</strong>：邮件礼仪教程获 25w+ 互动，高收藏（14w+）说明长尾价值内容仍有市场</li><li><strong>明星/娱乐</strong>：papi酱 相关内容、明星摔跤神图仍有高热度</li><li><strong>特效驱动</strong>：小红书新特效引发模仿热潮，30w+ 互动证明平台原生玩法吸流能力</li><li><strong>母婴/育儿</strong>：&quot;娃从小被练到大&quot; 26w+ 互动，育儿+搞笑内容结合是爆款公式</li></ul>',37)])])}const u=e(d,[["render",i]]);export{g as __pageData,u as default};
